/**
 * Replays deterministic futures data through the existing strategy without future-candle access, broker access, or order creation.
 * @summary Run a causal shadow backtest
 */
export const runBacktestBodySymbolDefault = `MES`;
export const runBacktestBodySymbolMax = 12;

export const runBacktestBodyEndDateDefault = `2026-08-25`;
export const runBacktestBodyEndDateRegExp = new RegExp('^\\d{4}-\\d{2}-\\d{2}$');
export const runBacktestBodyStartDateDefault = `2026-07-27`;
export const runBacktestBodyStartDateRegExp = new RegExp('^\\d{4}-\\d{2}-\\d{2}$');
export const runBacktestBodyInSampleDaysDefault = 5;
export const runBacktestBodyInSampleDaysMax = 22;

export const runBacktestBodyOutOfSampleDaysDefault = 2;
export const runBacktestBodyOutOfSampleDaysMax = 22;

export const runBacktestBodySeedDefault = 11;
export const runBacktestBodySeedMax = 100000;

export const runBacktestBodyPremarketAvailableDefault = true;
export const runBacktestBodyTargetDollarsDefault = 75;
export const runBacktestBodyTargetDollarsMin = 50;
export const runBacktestBodyTargetDollarsMax = 100;

export const runBacktestBodySlippageModeDefault = `normal`;
export const runBacktestBodySourceDefault = `simulated`;
export const runBacktestBodyOhlcvEntryBufferTicksDefault = 8;
export const runBacktestBodyOhlcvStopBufferTicksDefault = 8;
export const runBacktestBodyOhlcvSlippageTicksDefault = 1;
export const runBacktestBodyOhlcvSlippageTicksMin = 0;
export const runBacktestBodyOhlcvSlippageTicksMax = 8;

export const runBacktestBodyOhlcvCommissionPerContractMin = 0;



export const RunBacktestBody = zod.object({
  "symbol": zod.string().min(1).max(runBacktestBodySymbolMax).default(runBacktestBodySymbolDefault),
  "endDate": zod.string().regex(runBacktestBodyEndDateRegExp).default(runBacktestBodyEndDateDefault),
  "startDate": zod.string().regex(runBacktestBodyStartDateRegExp).default(runBacktestBodyStartDateDefault),
  "inSampleDays": zod.number().min(1).max(runBacktestBodyInSampleDaysMax).default(runBacktestBodyInSampleDaysDefault),
  "outOfSampleDays": zod.number().min(1).max(runBacktestBodyOutOfSampleDaysMax).default(runBacktestBodyOutOfSampleDaysDefault).describe('Single-run sessions share a maximum total of 22 across in-sample and holdout days.'),
  "seed": zod.number().min(1).max(runBacktestBodySeedMax).default(runBacktestBodySeedDefault),
  "premarketAvailable": zod.boolean().default(runBacktestBodyPremarketAvailableDefault),
  "targetDollars": zod.number().min(runBacktestBodyTargetDollarsMin).max(runBacktestBodyTargetDollarsMax).default(runBacktestBodyTargetDollarsDefault),
  "slippageMode": zod.enum(['normal', 'fast', 'abnormal_spread']).default(runBacktestBodySlippageModeDefault),
  "source": zod.enum(['simulated', 'historical_databento', 'historical_databento_multicontract']).default(runBacktestBodySourceDefault),
  "executionMode": zod.enum(['quote_based_shadow', 'ohlcv_modeled']).optional().describe('Quote-based Shadow requires bid\/ask; OHLCV modeled is restricted to the historical Databento source.'),
  "ohlcvEntryBufferTicks": zod.literal(8).default(runBacktestBodyOhlcvEntryBufferTicksDefault).describe('Exactly 8 MES ticks \/ 2.00 index points.'),
  "ohlcvStopBufferTicks": zod.literal(8).default(runBacktestBodyOhlcvStopBufferTicksDefault).describe('Exactly eight MES ticks beyond the frozen patience-candle extreme.'),
  "ohlcvSlippageTicks": zod.number().min(runBacktestBodyOhlcvSlippageTicksMin).max(runBacktestBodyOhlcvSlippageTicksMax).default(runBacktestBodyOhlcvSlippageTicksDefault),
  "ohlcvCommissionPerContract": zod.number().min(runBacktestBodyOhlcvCommissionPerContractMin).optional().describe('Round-trip commission and exchange\/regulatory fee assumption per contract.')
})

